// Normalize the Probo USER_CREATED payload and decide if this looks like a real new hire.
const src = $input.first().json;
const body = src.body || src;
const d = body.data || body.user || body;

const cfg = src;
const orgId = body.organizationId || d.organizationId || $('When New User in Probo').params.organizationId || null;

const email = String(d.emailAddress || d.email || '').trim().toLowerCase();
const at = email.lastIndexOf('@');
const local = at >= 0 ? email.slice(0, at).split('+')[0] : '';
const domain = at >= 0 ? email.slice(at + 1) : '';
const source = String(d.source || '').toUpperCase();
const kind = String(d.kind || '').toUpperCase();

const csv = s => String(s || '').split(',').map(x => x.trim().toLowerCase()).filter(Boolean);
const allowedDomains = csv(cfg.cfg_allowed_email_domains);
const blockedWords = new Set(csv(cfg.cfg_blocked_email_words));

const reasons = [];
if (!d.id) reasons.push('missing profile id');
if (!email || at < 1) reasons.push('missing or invalid email');
if (allowedDomains.length && !allowedDomains.includes(domain)) reasons.push('email domain ' + domain + ' is not in the allowed list');
if (cfg.cfg_only_scim_users && source && source !== 'SCIM') reasons.push('profile was not provisioned by SCIM (source ' + source + ')');
const tokens = [local, ...local.split(/[.\-_]/)].filter(Boolean);
const hit = tokens.find(t => blockedWords.has(t));
if (hit) reasons.push('email looks like a test or shared mailbox (' + hit + ')');
if (!String(d.fullName || '').trim()) reasons.push('missing full name');

return [{ json: {
  person_id: d.id || null,
  name: d.fullName || '',
  email,
  job_title: d.position || '',
  kind,
  source,
  org_id: orgId,
  wait_hours: Number(cfg.cfg_wait_hours) >= 0 ? Number(cfg.cfg_wait_hours) : 2,
  is_legit: reasons.length === 0,
  reject_reasons: reasons
} }];

// Merge the fresh profile with the snapshot taken before the wait.
// Stop here if the user was deactivated or removed in the meantime.
const snap = $('Verify User Authenticity').first().json;
const raw = $input.first().json || {};
const fresh = raw.data || raw.user || raw.profile || raw;

const state = String(fresh.state || fresh.membership?.state || 'ACTIVE').toUpperCase();
if (state !== 'ACTIVE') return [];

const jobTitle = String(fresh.position || snap.job_title || '').trim();
return [{ json: {
  ...snap,
  name: fresh.fullName || snap.name,
  email: String(fresh.emailAddress || snap.email || '').toLowerCase(),
  kind: String(fresh.kind || snap.kind || '').toUpperCase(),
  job_title: jobTitle,
  has_job_title: jobTitle !== ''
} }];

// One item out: the user + every policy (latest published version, plain text excerpt).
const person = $('Merge Active User Profiles').first().json;
const MAX_CHARS = 4000;

const toText = c => {
  if (!c) return '';
  let doc = c;
  if (typeof c === 'string') {
    try { doc = JSON.parse(c); } catch (e) { return c; }
  }
  const out = [];
  const walk = n => {
    if (!n) return;
    if (Array.isArray(n)) return n.forEach(walk);
    if (typeof n.text === 'string') out.push(n.text);
    if (n.content) walk(n.content);
    if (['paragraph', 'heading', 'listItem'].includes(n.type)) out.push('\n');
  };
  walk(doc);
  return out.join(' ').replace(/[ \t]+/g, ' ').replace(/\n\s*/g, '\n').trim();
};

const seen = new Set();
const policies = [];
for (const it of $input.all()) {
  const j = it.json || {};
  const v = Array.isArray(j.versions) ? j.versions[0] : (Array.isArray(j.data?.versions) ? j.data.versions[0] : j);
  if (!v || !v.id || seen.has(v.id)) continue;
  if (v.status && String(v.status).toUpperCase() !== 'PUBLISHED') continue;
  seen.add(v.id);
  policies.push({
    version_id: v.id,
    title: v.title || '',
    content: toText(v.content).slice(0, MAX_CHARS)
  });
}
if (policies.length === 0) return [];

const prompt = 'New employee\n- Name: ' + person.name + '\n- Job title: ' + (person.job_title || '(empty)') +
  '\n- Employment kind: ' + (person.kind || '(unknown)') + '\n\nPolicies:\n' +
  policies.map(p => '### version_id: ' + p.version_id + '\nTitle: ' + p.title + '\nContent:\n' + (p.content || '(empty)')).join('\n\n');

return [{ json: { ...person, policies, policy_count: policies.length, agent_prompt: prompt } }];

// Parse the agent answer. Any policy without a clear SKIP is sent (fail-safe).
const ctx = $('Compile User and Policy Data').first().json;
const raw = String($input.first().json.output ?? $input.first().json.text ?? '').trim()
  .replace(/^\s*```(json)?/i, '').replace(/```\s*$/, '').trim();

let decisions = [];
try {
  const parsed = JSON.parse(raw);
  if (Array.isArray(parsed)) decisions = parsed;
} catch (e) {
  decisions = [];
}
const byId = {};
for (const d of decisions) if (d && d.version_id) byId[d.version_id] = d;

return ctx.policies
  .filter(p => String(byId[p.version_id]?.action || 'SEND').toUpperCase() !== 'SKIP')
  .map(p => ({ json: {
    person_id: ctx.person_id,
    person_name: ctx.name,
    version_id: p.version_id,
    title: p.title,
    reason: byId[p.version_id]?.reason || 'No clear decision, sent by default'
  } }));

// No job title after the wait: we cannot scope, so every published policy is sent.
const ctx = $input.first().json;
return ctx.policies.map(p => ({ json: {
  person_id: ctx.person_id,
  person_name: ctx.name,
  version_id: p.version_id,
  title: p.title,
  reason: 'No job title on the profile, all policies sent'
} }));

// Build one Slack recap from all signature requests (sent + failed).
const person = $('Merge Active User Profiles').first().json;
const upstream = $('Select Policies to Send').isExecuted
  ? $('Select Policies to Send').all()
  : $('Dispatch All Policies').all();
const results = $input.all();

const sent = [];
const failed = [];
results.forEach((it, i) => {
  const title = upstream[i]?.json?.title || 'Untitled policy';
  if (it.json && it.json.error) failed.push(title);
  else sent.push(title);
});

const who = person.name + ' (' + person.email + (person.job_title ? ', ' + person.job_title : ', no job title') + ')';
let text = ':white_check_mark: *Onboarding: policies sent for signature*\n' + who + ' received ' + sent.length + ' ' + (sent.length === 1 ? 'policy' : 'policies') + ' to sign:\n' + sent.map(t => '• ' + t).join('\n');
if (failed.length) text += '\n\n:x: ' + failed.length + ' request(s) failed:\n' + failed.map(t => '• ' + t).join('\n');

return [{ json: { slack_text: text, sent_count: sent.length, failed_count: failed.length } }];
